#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>

using namespace std;

struct Edge {
    int to, rev;
    int cap;
};

class Dinic {
public:
    vector<vector<Edge>> graph;
    vector<int> level, iter;
    Dinic(int n) : graph(n), level(n), iter(n) {}
    void add_edge(int from, int to, int cap) {
        graph[from].push_back({to, (int)graph[to].size(), cap});
        graph[to].push_back({from, (int)graph[from].size()-1, 0});
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto& e : graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int& i = iter[v]; i < (int)graph[v].size(); ++i) {
            Edge& e = graph[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    int max_flow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            fill(iter.begin(), iter.end(), 0);
            int f;
            while ((f = dfs(s, t, INT_MAX)) > 0)
                flow += f;
        }
        return flow;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;

    vector<string> nau(n), pom(n);
    for (auto& s : nau) cin >> s;
    for (auto& s : pom) cin >> s;

    vector<vector<int>> odl(n, vector<int>(n, 1000));
    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] == 'Z') { sx = i; sy = j; }

    const int dx[] = {-1, 0, 1, 0, 0};
    const int dy[] = {0, 1, 0, -1, 0};

    auto ok = [n](int x, int y) { return x >= 0 && x < n && y >= 0 && y < n; };

    queue<pair<int,int>> q;
    odl[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (ok(nx, ny) && nau[nx][ny] >= '0' && nau[nx][ny] <= '9' && odl[nx][ny] == 1000) {
                odl[nx][ny] = odl[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    bool moge[60][10][10][10][10] = {};

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int d = 0; d < 5; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (ok(ni, nj) && nau[i][j] >= '0' && nau[i][j] <= '9' && nau[ni][nj] >= '0' && nau[ni][nj] <= '9')
                    moge[0][i][j][ni][nj] = true;
            }

    for (int k = 0; k <= t - 2; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int l = 0; l < n; ++l)
                    for (int m = 0; m < n; ++m) {
                        if (!moge[k][i][j][l][m]) continue;
                        for (int d = 0; d < 5; ++d) {
                            int nl = l + dx[d], nm = m + dy[d];
                            if (ok(nl, nm) && nau[nl][nm] >= '0' && nau[nl][nm] <= '9' && odl[l][m] >= k+2 && odl[nl][nm] >= k+2)
                                moge[k+1][i][j][nl][nm] = true;
                        }
                    }

    vector<pair<int,int>> a;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] >= '0' && nau[i][j] <= '9')
                a.push_back({i, j});

    int V = 2 * a.size() + 2;
    Dinic dinic(V);
    for (int i = 0; i < (int)a.size(); ++i) {
        int c1 = nau[a[i].first][a[i].second] - '0';
        int c2 = pom[a[i].first][a[i].second] - '0';
        dinic.add_edge(0, i+1, c1);
        dinic.add_edge(a.size()+1+i, V-1, c2);
    }

    for (int i = 0; i < (int)a.size(); ++i)
        for (int j = 0; j < (int)a.size(); ++j) {
            bool reach = false;
            for (int k = 0; k <= t-1; ++k)
                if (moge[k][a[i].first][a[i].second][a[j].first][a[j].second]) {
                    reach = true;
                    break;
                }
            if (reach)
                dinic.add_edge(i+1, a.size()+1+j, 1000);
        }

    cout << dinic.max_flow(0, V-1);
    return 0;
}
